import{_ as n,o as i,c as r,b6 as t,bT as s,bU as a,bV as l,bW as o,bX as d,bY as g,bZ as u,b_ as h,b$ as m,c0 as c,c1 as b,c2 as p,c3 as f,c4 as k,c5 as w,c6 as P,c7 as z,c8 as v,c9 as S,ca as A,cb as _,cc as I,cd as W,ce as E,cf as D,cg as C,ch as V,ci as x,cj as q,ck as T,cl as K,cm as B,cn as G,co as N,cp as U}from"./chunks/framework.BUXTSoD9.js";const H=JSON.parse('{"title":"Sieben AI-Programmier-Tools im Vergleich","description":"","frontmatter":{},"headers":[],"relativePath":"de-de/stage-1/appendix-articles/example0-1/vibe-coding-tools-snake-game-tutorial.md","filePath":"de-de/stage-1/appendix-articles/example0-1/vibe-coding-tools-snake-game-tutorial.md"}'),F={name:"de-de/stage-1/appendix-articles/example0-1/vibe-coding-tools-snake-game-tutorial.md"};function L(j,e,y,Z,M,R){return i(),r("div",null,[...e[0]||(e[0]=[t('<h1 id="sieben-ai-programmier-tools-im-vergleich" tabindex="-1">Sieben AI-Programmier-Tools im Vergleich <a class="header-anchor" href="#sieben-ai-programmier-tools-im-vergleich" aria-label="Permalink to “Sieben AI-Programmier-Tools im Vergleich”">​</a></h1><h2 id="kapitel-uuml-bersicht" tabindex="-1">Kapitelübersicht <a class="header-anchor" href="#kapitel-uuml-bersicht" aria-label="Permalink to “Kapitel&amp;uuml;bersicht”">​</a></h2><p>Angesichts der schillernden Auswahl an AI-Programmier-Tools: Welches ist das richtige für Sie? Dieses Kapitel vergleicht 7 gängige Web Vibe Coding Plattformen wie Lovable, Replit, Z.ai usw. anhand einer einheitlichen Praxisaufgabe – der Entwicklung eines &quot;Snake + AI-Poesie&quot;-Spiels. Wir vergleichen sie aus mehreren Dimensionen wie Anfängerfreundlichkeit, Code-Kontrollierbarkeit und Bereitstellungskomfort, um Ihnen bei der schnellen Auswahl des besten Entwicklungstools zu helfen.</p><hr><h1 id="_1-snake-spiel-mit-vibe-coding-erstellen-vollst-auml-ndiges-praxis-tutorial" tabindex="-1">1. Snake-Spiel mit Vibe Coding erstellen: Vollständiges Praxis-Tutorial <a class="header-anchor" href="#_1-snake-spiel-mit-vibe-coding-erstellen-vollst-auml-ndiges-praxis-tutorial" aria-label="Permalink to “1. Snake-Spiel mit Vibe Coding erstellen: Vollst&amp;auml;ndiges Praxis-Tutorial”">​</a></h1><p>Dieser Artikel stellt eine neue Softwareentwicklungspraxis vor – &quot;Vibe Coding&quot;, die KI nutzt, um den Anwendungsentwicklungsprozess zu beschleunigen.</p><p>Als Nächstes werden wir nacheinander die Kernkonzepte von Vibe Coding vorstellen, erklären, was ein AI Agent ist, und praktische Methoden zum Schreiben von Prompts geben. Schließlich werden wir durch eine vollständige Praxis das &quot;Snake&quot;-Spiel von Grund auf erstellen und mehrere gängige Vibe Coding Plattformen im Detail vergleichen, um Ihnen bei der Auswahl der besten Tool-Kombination zu helfen.</p><h2 id="was-sie-lernen-werden" tabindex="-1">Was Sie lernen werden: <a class="header-anchor" href="#was-sie-lernen-werden" aria-label="Permalink to “Was Sie lernen werden:”">​</a></h2><ul><li><strong>Was ist Vibe Coding</strong>: Definition, Workflow und wichtigste Vorteile verstehen.</li><li><strong>Die Rolle von AI Agents</strong>: Arbeitsweise von AI Agents und Unterschiede zu traditionellen Programmen verstehen.</li><li><strong>Wie man gute Prompts schreibt</strong>: Klare, spezifische Prompt-Formulierungen für bessere Ergebnisse beherrschen.</li><li><strong>Vibe Coding Tools</strong>: Eine Reihe gängiger AI-Programmier- und Design-Plattformen kennenlernen.</li><li><strong>Plattform-Vergleich</strong>: Bewertung und Vergleich der Vor- und Nachteile von 7 verschiedenen AI Agent Plattformen aus der Perspektive von Einsteigern.</li><li><strong>UI / UX Tools</strong>: Lernen, wie man Figma, Mastergo und andere UI/UX-Tools in den gesamten Workflow integriert.</li></ul><h2 id="_1-einleitung" tabindex="-1">1. Einleitung <a class="header-anchor" href="#_1-einleitung" aria-label="Permalink to “1. Einleitung”">​</a></h2><p>In den bisherigen Kursen haben wir stets das Full-Stack-Entwicklungsmodell von z.ai für Programmieraufgaben verwendet.</p><p>Haben wir uns jedoch jemals gefragt: Sein Kern ist eigentlich der &quot;AI Agent&quot; (anders als gewöhnliche Chat-KI und viel intelligenter)? Denn es kommuniziert nicht nur mit Ihnen, sondern kann auch denken (wenn Sie ihm eine Aufgabe geben, plant es zunächst) und proaktiv handeln (z.B. Web-Suche aufrufen, Computerbefehle ausführen, Webseiten öffnen). Wir werden später darauf zurückkommen.</p><h2 id="_1-was-ist-vibe-coding" tabindex="-1">1. Was ist Vibe Coding? <a class="header-anchor" href="#_1-was-ist-vibe-coding" aria-label="Permalink to “1. Was ist Vibe Coding?”">​</a></h2><p>Vibe Coding ist eine neue Softwareentwicklungsmethode, die KI nutzt, um den Anwendungsentwicklungsprozess zu beschleunigen. Es ist kein Ersatz für traditionelle Programmierung, sondern ein &quot;konversationelleres&quot; Programmiermodell. Dieses Konzept wurde vom AI-Forscher Andrej Karpathy vorgeschlagen: In diesem Workflow schreiben Entwickler nicht mehr Zeile für Zeile Code selbst, sondern steuern hauptsächlich AI Agents, um Anwendungen zu generieren, zu optimieren und zu debuggen.</p><p>Die Kernidee von Vibe Coding ist der Übergang von <strong>&quot;code-first&quot;</strong> zu <strong>&quot;intent-first&quot;</strong>. Sie müssen nicht mehr ab der ersten Codezeile planen, sondern beschreiben das gewünschte Ergebnis in natürlicher Sprache.</p><p>Ein typischer Vibe Coding-Workflow ist ein iterativer Kreislauf:</p><ul><li><strong>Ziel beschreiben</strong>: Zunächst mit einem Satz oder Absatz beschreiben, was Sie implementieren möchten, z.B.: &quot;Ein einfaches Snake-Spiel mit Python-Backend, das Gedichte generieren kann.&quot;</li><li><strong>AI generiert Code</strong>: Der AI Agent analysiert Ihre Anforderungen, generiert eine erste Codeversion mit grundlegender Struktur, Frontend-Seiten und Backend-Logik.</li><li><strong>Ausführen und beobachten</strong>: Den generierten Code ausführen, prüfen, ob er wie erwartet funktioniert, und dabei Bugs oder Schwächen entdecken.</li><li><strong>Feedback geben und iterieren</strong>: Bei Fehlern oder unbefriedigenden Ergebnissen im Dialog weiter instruieren, z.B.: &quot;Die Schlange bewegt sich zu langsam, mach sie schneller&quot; oder &quot;Der API Key in der <code>.env</code>-Datei wird nicht richtig gelesen, bitte den Backend-Code reparieren.&quot;</li><li><strong>Obige Schritte wiederholen</strong>: Kontinuierlich im Kreislauf &quot;Beschreiben → Generieren → Ausführen → Feedback&quot; iterieren, bis die Anwendung zufrieden stellend ist.</li></ul><h3 id="die-wichtigsten-vorteile-von-vibe-coding" tabindex="-1">Die wichtigsten Vorteile von Vibe Coding: <a class="header-anchor" href="#die-wichtigsten-vorteile-von-vibe-coding" aria-label="Permalink to “Die wichtigsten Vorteile von Vibe Coding:”">​</a></h3><ul><li><strong>Einstiegshürde senken</strong>: Auch Designer, Gründer und Studierende ohne Programmiererfahrung können durch natürliche Sprache an der Anwendungsentwicklung teilnehmen.</li><li><strong>Schnelle Prototypen</strong>: Die Zeit von der Idee zum MVP (Minimum Viable Product) wird drastisch verkürzt.</li><li><strong>Effizienz steigern</strong>: Automatische Erledigung großer Mengen repetitiver, mechanischer Codierungsarbeit (wie Boilerplate-Code), sodass Entwickler sich auf Architektur-Design und Probleabstraktion konzentrieren können.</li><li><strong>Experimentieren fördern</strong>: Ermutigt zu schnellem Ergebnis und kontinuierlicher Verbesserung, was das Ausprobieren neuer Ideen und Funktionen erleichtert.</li></ul><h2 id="_2-was-sind-vibe-coding-online-plattformen-web-based" tabindex="-1">2. Was sind Vibe Coding Online-Plattformen (Web-based)? <a class="header-anchor" href="#_2-was-sind-vibe-coding-online-plattformen-web-based" aria-label="Permalink to “2. Was sind Vibe Coding Online-Plattformen (Web-based)?”">​</a></h2><p>In diesem Praxis-Test werden Sie feststellen, dass die von uns bewerteten Tools in zwei Kategorien eingeteilt werden: <strong>Web-based (Online-Plattformen)</strong> und <strong>IDE (lokale Entwicklungsumgebungen)</strong>.</p><p>Obwohl beide im Kern AI-gestützt Code schreiben, gibt es gewaltige Unterschiede in der Nutzererfahrung und den Anwendungsszenarien:</p><h3 id="vibe-coding-online-plattformen-web-based" tabindex="-1">Vibe Coding Online-Plattformen (Web-based) <a class="header-anchor" href="#vibe-coding-online-plattformen-web-based" aria-label="Permalink to “Vibe Coding Online-Plattformen (Web-based)”">​</a></h3><p><strong>Repräsentative Tools:</strong> Lovable, Replit, Z.ai, v0</p><p>Das ist wie ein &quot;Ready-to-move-in&quot;-Hotelapartment.</p><ul><li><strong>Keine Umgebungskonfiguration nötig</strong>: Sie müssen sich nicht um Python-Umgebung, Node.js-Version oder Abhängigkeitsinstallation kümmern. Browser öffnen, URL eingeben, direkt loslegen.</li><li><strong>Ein-Klick-Vorschau und Bereitstellung</strong>: Nach der Codegenerierung zeigt die Plattform das Ergebnis automatisch in einem Seitenfenster an. Wenn fertig, einen Klick, um einen Link zu generieren und mit Freunden zu teilen.</li><li><strong>Geeignete Szenarien:</strong><ul><li><strong>Schnelle Ideenvalidierung (MVP)</strong>: Eine Idee im Kopf, mal eine halbe Stunde ausprobieren.</li><li><strong>Einsteiger</strong>: Komplett frei von komplexen Umgebungsfehlern, nur die Freude an AI-Programmierung erleben.</li><li><strong>Leichtgewichtige Anwendungen</strong>: Eine einfache Tool-Webseite, ein kleines Spiel oder eine persönliche Präsentationsseite.</li></ul></li></ul><h3 id="ai-ide-lokale-entwicklungsumgebung" tabindex="-1">AI IDE (Lokale Entwicklungsumgebung) <a class="header-anchor" href="#ai-ide-lokale-entwicklungsumgebung" aria-label="Permalink to “AI IDE (Lokale Entwicklungsumgebung)”">​</a></h3><p><strong>Repräsentative Tools:</strong> Cursor, Trae, VS Code + AI-Plugin</p><p>Das ist wie ein &quot;voll ausgestattetes&quot; Eigenheim.</p><ul><li><strong>Starke lokale Fähigkeiten</strong>: Läuft auf Ihrem Computer, hat direkten Zugriff auf alle Ihre lokalen Dateien und nutzt die Rechenleistung Ihres Computers.</li><li><strong>Nahtlose professionelle Workflow-Integration</strong>: Geeignet für große Projekte, freie Plugin-Installation, Verbindung zu lokalen Datenbanken, komplexes Debugging.</li><li><strong>Geeignete Szenarien:</strong><ul><li><strong>Professionelle Projektentwicklung</strong>: Langfristig zu wartende, strukturell komplexe kommerzielle Projekte.</li><li><strong>Tiefe Anpassung</strong>: Extreme Code-Kontrolle oder tiefe Integration mit bestehendem lokalem Workflow (wie Git, Docker).</li><li><strong>Datenschutz</strong>: Code komplett lokal, besser konform zu Sicherheitsrichtlinien mancher Unternehmen.</li></ul></li></ul><p><strong>Zusammenfassend:</strong> Wenn Sie gerade erst mit AI-Programmierung beginnen oder nur schnell etwas Kleines ausprobieren wollen, sind <strong>Online-Plattformen</strong> der perfekte Startpunkt. Wenn Sie professioneller Entwickler sind oder das Projekt immer komplexer wird, bietet eine <strong>lokale IDE</strong> eine höhere Obergrenze.</p><hr><h2 id="_3-was-ist-ein-ai-agent" tabindex="-1">3. Was ist ein AI Agent? <a class="header-anchor" href="#_3-was-ist-ein-ai-agent" aria-label="Permalink to “3. Was ist ein AI Agent?”">​</a></h2><h3 id="was-ist-ein-ai-agent" tabindex="-1">Was ist ein AI Agent? <a class="header-anchor" href="#was-ist-ein-ai-agent" aria-label="Permalink to “Was ist ein AI Agent?”">​</a></h3><p>Ein AI Agent ist ein Softwaresystem, das seine Umgebung wahrnehmen, Entscheidungen treffen und autonom handeln kann, um bestimmte Ziele zu erreichen. Im Vergleich zu traditioneller Software, die festen Anweisungen folgt und einen einzigen Prozessablauf hat, sind AI Agents flexibler und anpassungsfähiger.</p><p>Hier sind einige Schlüsseleigenschaften, die AI Agents von traditionellen Programmen unterscheiden:</p><ul><li><strong>Autonomie</strong>: AI Agents haben hohe Unabhängigkeit. Traditionelle Programme müssen meist Schritt für Schritt von Menschen ausgelöst werden, während ein Agent basierend auf seinem Ziel selbst entscheiden kann, was er als Nächstes tun soll.</li><li><strong>Wahrnehmung und Gedächtnis</strong>: Agents sammeln Daten aus der Umgebung (z.B. API-Antworten, Sensordaten, Nutzereingaben) und behalten Kontext durch &quot;Gedächtnis&quot;, um Erfahrung in späteren Aktionen wiederzuverwenden und die Leistung kontinuierlich zu verbessern.</li><li><strong>Rationalität und Zielorientierung</strong>: Agents analysieren und planen um ein gegebenes Ziel herum und wählen die geeignete Aktionssequenz, um höhere &quot;Leistungskennzahlen&quot; zu verfolgen.</li><li><strong>Werkzeugnutzung</strong>: Ein Hauptmerk moderner AI Agents ist die Fähigkeit, externe Tools aufzurufen und nicht auf &quot;Textgenerierung&quot; beschränkt zu bleiben. Sie können z.B. Webseiten durchsuchen, Code ausführen, Datenbanken abfragen, E-Mails senden – ein Gehirn, das &quot;Tools orchestriert&quot;.</li></ul><p>Man kann es sich so vorstellen:</p><ul><li>Ein <strong>traditionelles Programm</strong> ist wie ein Taschenrechner. Man gibt Zahlen und Operatoren ein, es rechnet nur, wenn man den Knopf drückt.</li><li>Ein <strong>AI-Assistent</strong> ist wie ein menschlicher Assistent. Man bittet ihn &quot;Finde Restaurants in meiner Nähe&quot;, er gibt Suchergebnisse und listet Optionen auf, aber die Entscheidung trifft am Ende man selbst.</li><li>Ein <strong>AI Agent</strong> ist eher wie ein automatisiertes Forschungsteam. Man gibt nur ein hochrangiges Ziel (z.B. &quot;Plane eine Japanreise für mich&quot;), und es zerlegt die Aufgabe, recherchiert online, bucht Flüge und Hotels (per API), erstellt einen Zeitplan und liefert das Ergebnis – fast ohne dass Sie sich um Details kümmern müssen.</li></ul><hr><h1 id="_2-zum-thema-prompt-schreiben" tabindex="-1">2. Zum Thema Prompt-Schreiben <a class="header-anchor" href="#_2-zum-thema-prompt-schreiben" aria-label="Permalink to “2. Zum Thema Prompt-Schreiben”">​</a></h1><h2 id="_1-prompt-am-besten-auf-einmal-oder-in-mehreren-schritten-schreiben" tabindex="-1">1. Prompt am besten auf einmal oder in mehreren Schritten schreiben? <a class="header-anchor" href="#_1-prompt-am-besten-auf-einmal-oder-in-mehreren-schritten-schreiben" aria-label="Permalink to “1. Prompt am besten auf einmal oder in mehreren Schritten schreiben?”">​</a></h2><p>Viele sind versucht, in einem einzigen Prompt &quot;eine vollständige Full-Stack-Anwendung&quot; zu beschreiben. Tatsächlich sind die aktuellen Tools bereits leistungsstark genug, um möglicherweise auf einmal ein einigermaßen akzeptables Ergebnis zu liefern. Insgesamt ist es jedoch oft besser, die Arbeit in kleine Schritte zu unterteilen und phasenweise zu iterieren, um nicht in einer &quot;nicht mehr änderbaren&quot; Sackgasse zu landen.</p><blockquote><p><strong>Kleiner Tipp:</strong> Anstatt &quot;alles auf einmal&quot; zu erwarten, lieber das große Ziel in ausführbare kleine To-dos aufteilen. Zum Beispiel: Nicht direkt &quot;build me a Snake game&quot; sagen, sondern aufteilen in: &quot;1. Zunächst ein Snake-Spiel-Frontend erstellen&quot;, &quot;2. Dann ein Backend zur Punkteaufzeichnung implementieren&quot;, &quot;3. Schließlich Frontend und Backend verbinden&quot;. So kann AI Ihre Anforderungen genauer verstehen und zuverlässigere Ergebnisse liefern.</p></blockquote><h2 id="_2-je-klarer-desto-besser" tabindex="-1">2. Je klarer, desto besser <a class="header-anchor" href="#_2-je-klarer-desto-besser" aria-label="Permalink to “2. Je klarer, desto besser”">​</a></h2><ul><li>In Vibe Coding sind Ihre geschriebenen Prompts genauso wichtig wie Ihr geschriebener Code. Je klarer und spezifischer der Prompt, desto näher ist das Ergebnis an dem, was Sie sich vorstellen.</li><li>Ziel und Einschränkungen von Anfang an klar formulieren, reduziert spätere Änderungen, was nicht nur Zeit spart, sondern auch Kontingent und Kosten.</li></ul><hr><h1 id="_3-tool-uuml-bersicht-vibe-coding-uiux-tools" tabindex="-1">3. Tool-Übersicht (Vibe Coding / UIUX Tools) <a class="header-anchor" href="#_3-tool-uuml-bersicht-vibe-coding-uiux-tools" aria-label="Permalink to “3. Tool-&amp;Uuml;bersicht (Vibe Coding / UIUX Tools)”">​</a></h1><h2 id="_1-ai-agent-plattformen" tabindex="-1">1. AI Agent Plattformen <a class="header-anchor" href="#_1-ai-agent-plattformen" aria-label="Permalink to “1. AI Agent Plattformen”">​</a></h2><table tabindex="0"><thead><tr><th><strong>Name</strong></th><th><strong>Plattform</strong></th></tr></thead><tbody><tr><td><strong><a href="https://lovable.dev/" target="_blank" rel="noreferrer">Lovable</a></strong></td><td>Web-based</td></tr><tr><td><strong><a href="https://cursor.com/cn/agents" target="_blank" rel="noreferrer">Cursor</a></strong></td><td>PC</td></tr><tr><td><strong><a href="https://chat.z.ai/" target="_blank" rel="noreferrer">Z.ai</a></strong></td><td>Web-based</td></tr><tr><td><strong><a href="https://replit.com/~" target="_blank" rel="noreferrer">Replit</a></strong></td><td>Web-based</td></tr><tr><td><strong><a href="https://agent.minimaxi.com/" target="_blank" rel="noreferrer">Minimax</a></strong></td><td>Web-based</td></tr><tr><td><strong><a href="https://www.trae.ai/" target="_blank" rel="noreferrer">Trae</a></strong></td><td>PC</td></tr><tr><td><strong><a href="https://v0.app/" target="_blank" rel="noreferrer">V0</a></strong></td><td>Web-based</td></tr></tbody></table><h2 id="_2-ai-uiux-plattformen" tabindex="-1">2. AI UIUX Plattformen <a class="header-anchor" href="#_2-ai-uiux-plattformen" aria-label="Permalink to “2. AI UIUX Plattformen”">​</a></h2><table tabindex="0"><thead><tr><th><strong>Name</strong></th><th><strong>Plattform</strong></th></tr></thead><tbody><tr><td><strong><a href="https://mastergo.com/" target="_blank" rel="noreferrer">Mastergo</a></strong></td><td>Web-based</td></tr><tr><td><strong><a href="https://www.figma.com/" target="_blank" rel="noreferrer">Figma</a></strong></td><td>Web-based, PC-Plugin</td></tr></tbody></table><hr><h1 id="_4-praxis-tutorial-vibe-coding-ui-kombination" tabindex="-1">4. Praxis-Tutorial (Vibe Coding + UI Kombination) <a class="header-anchor" href="#_4-praxis-tutorial-vibe-coding-ui-kombination" aria-label="Permalink to “4. Praxis-Tutorial (Vibe Coding + UI Kombination)”">​</a></h1><ol><li><p>Geben Sie im Chat-Fenster der Vibe Coding Plattform Ihre Programmbeschreibung ein. Beispiel:</p><blockquote><p>Bitte erstellen Sie eine einfache Snake-Webanwendung mit Frontend und Backend.</p><ol><li>Frontend</li></ol><ul><li>Seite 1: Spiel-Seite <ul><li>Tastatursteuerung der Schlangenbewegung.</li><li>Die Schlange frisst keine Nahrung, sondern englische Wörter.</li><li>Seitenleiste zeigt gesammelte Wörter und deren Anzahl.</li><li>Nach Spielende bleiben gesammelte Wörter erhalten und werden im nächsten Spiel fortgesetzt.</li></ul></li><li>Seite 2: Gedicht-Seite (Make Poem) <ul><li>Dieselbe Wortliste wie auf der Spiel-Seite anzeigen (Datenkonsistenz).</li><li>Einen Button zum Senden der aktuell gesammelten Wörter an das Backend zur Generierung eines Gedichts.</li><li>Nach Gedichtgenerierung die verwendeten Wörter aus der Liste entfernen oder deren Zähler verringern.</li></ul></li></ul><ul><li>Einfache Navigation zum Wechseln zwischen Game und Make Poem.</li><li>Sicherstellen, dass gesammelte Wörter auf beiden Seiten sichtbar sind.</li></ul><ol start="2"><li>Backend</li></ol><ul><li>Backend-Schnittstelle bereitstellen, die gesammelte Wörter empfängt und ein Gedicht zurückgibt.</li><li>DeepSeek API zur Gedichtgenerierung verwenden.</li><li>API Key in <code>.env</code>-Datei speichern und in <code>.gitignore</code> ignorieren.</li></ul></blockquote></li><li><p>DeepSeek API Key eingeben. (Erhältlich unter <a href="https://platform.deepseek.com/" target="_blank" rel="noreferrer">https://platform.deepseek.com/</a>)</p><ol><li>Der API Key des LLM wird verwendet, um große Modelle in Ihrem eigenen Projekt aufzurufen. Da es sich um sensible Informationen handelt, die nicht öffentlich sein dürfen, muss er separat in einer Konfigurationsdatei gespeichert werden. <strong>Warum eine <code>.env</code>-Datei verwenden und sie nicht auf GitHub hochladen?</strong></li></ol><ul><li>Die <code>.env</code>-Datei dient speziell zur Speicherung von <strong>Schlüsseln oder Passwörtern</strong> (z.B. DeepSeek API Key).</li><li>Wenn diese Datei auf GitHub hochgeladen wird, kann jeder Ihren Schlüssel sehen und missbrauchen.</li><li>Aus Sicherheitsgründen müssen wir <code>.env</code> in der <code>.gitignore</code>-Datei deklarieren, damit Git sie nicht verfolgt.</li><li>So kann Ihr Projekt diese Schlüssel lokal weiterhin nutzen, ohne sie im Repository preiszugeben.</li></ul></li><li><p>Nachdem das Ergebnis angezeigt wurde, können Sie bei Fehlern oder gewünschten Änderungen Ihre Änderungswünsche direkt im Chat-Fenster eingeben.</p></li><li><p>Wenn Sie mit dem Seitendesign unzufrieden sind, können Sie das Interface auch in Figma oder Mastergo neu gestalten und die Designideen an den Agent zurückmelden.</p></li></ol><ul><li><strong>Beispiel</strong></li></ul><blockquote><p>Bitte entwerfen Sie eine <strong>zweiseitige Web-Anwendung</strong> namens <em>Word-Snake</em>.</p><ul><li><strong>Game-Seite:</strong></li><li>Schlange wird per Tastatur gesteuert.</li><li>Die Schlange frisst englische Wörter statt normale Nahrung.</li><li>Rechtes Panel zeigt gesammelte Wörter und deren Anzahl.</li><li>Nach Spielende wird der Wortbestand nicht gelöscht, sondern im nächsten Spiel weiterverwendet.</li><li><strong>Make Poem-Seite:</strong></li><li>Denselben gemeinsamen Wortbestand anzeigen.</li><li>Nutzer wählt einige Wörter aus und klickt auf <strong>Generate Poem</strong>-Button.</li><li>Diese Wörter an das Backend senden, das DeepSeek API generiert ein Gedicht.</li><li>Nach Gedichtgenerierung die verwendeten Wörter aus dem Bestand löschen oder verringern.</li><li><strong>Navigation:</strong> Einfacher Tab oder Top-Menü zum Wechseln zwischen den beiden Seiten.</li><li><strong>Gemeinsamer Zustand:</strong> Sicherstellen, dass gesammelte Wörter auf beiden Seiten stets synchron sichtbar sind.</li></ul></blockquote><ul><li><strong>Ergebnis-Beispiel</strong></li></ul><p><img src="'+s+'" alt=""><img src="'+a+'" alt=""></p><hr><h1 id="_5-ai-agent-plattform-vergleich-wie-man-die-beste-kombination-f-uuml-r-einfache-projekte-w-auml-hlt" tabindex="-1">5. AI Agent Plattform-Vergleich (Wie man die beste Kombination für einfache Projekte wählt) <a class="header-anchor" href="#_5-ai-agent-plattform-vergleich-wie-man-die-beste-kombination-f-uuml-r-einfache-projekte-w-auml-hlt" aria-label="Permalink to “5. AI Agent Plattform-Vergleich (Wie man die beste Kombination f&amp;uuml;r einfache Projekte w&amp;auml;hlt)”">​</a></h1><p>Verschiedene Vibe Coding Plattformen haben unterschiedliche Stärken und Workflows. Wir haben denselben &quot;Snake-Spiel mit DeepSeek API&quot;-Anforderungssatz auf mehreren Plattformen getestet und aus der Perspektive von Einsteigern bewertet. Hier ist die Zusammenfassung.</p><h2 id="_1-vergleichskriterien" tabindex="-1">1. Vergleichskriterien <a class="header-anchor" href="#_1-vergleichskriterien" aria-label="Permalink to “1. Vergleichskriterien”">​</a></h2><ol><li><p><strong>Ziel</strong> Ein Snake-Web-App mit DeepSeek API integrieren.</p></li><li><p><strong>Spieldetails</strong></p><ol><li>Das Spiel generiert Gedichte über die DeepSeek LLM API.</li><li>Die Schlange frisst englische Wörter; gesammelte Wörter bleiben nach Spielende erhalten und werden im nächsten Spiel weiterverwendet. Gleiche Wörter können mehrfach gesammelt und separat gezählt werden.</li><li>Wenn ein Gedicht generiert wird, werden die verwendeten Wörter aus dem Bestand entfernt.</li></ol></li><li><p><strong>Must-Haves</strong></p><ol><li>Eine lauffähige Frontend-Seite mit Snake-Spiel (Tastatursteuerung, Canvas-Rendering).</li><li>Wort-Sammelmechanismus (Wörter erscheinen auf dem Brett, Schlange frisst sie, Seitenleiste-Liste wird aktualisiert).</li><li>Persistenz des Wortbestands über mehrere Spielrunden.</li><li>Backend mit DeepSeek API (ohne API Key zunächst ein Mock-Gedicht zurückgeben).</li><li>&quot;Gedicht generieren&quot;-Button: Klick ruft Backend auf, zeigt Gedicht, aktualisiert Wortbestand basierend auf Nutzung.</li><li><code>.env</code>-Unterstützung für API Key und <code>.gitignore</code> zur Vermeidung von Schlüssellecks.</li></ol></li><li><p><strong>Nice-to-Haves</strong></p><ol><li>Nutzer kann auswählen, welche Wörter für das Gedicht verwendet werden.</li><li>Nutzerfreundliche Erfahrung (z.B. klare Wortliste in der Seitenleiste, gutes Layout im Gedicht-Bereich).</li><li>Kommentare im Code für Einsteiger, die die Schlüssellogik erklären.</li></ol></li></ol><h2 id="_2-codierungsergebnis-vergleich" tabindex="-1">2. Codierungsergebnis-Vergleich <a class="header-anchor" href="#_2-codierungsergebnis-vergleich" aria-label="Permalink to “2. Codierungsergebnis-Vergleich”">​</a></h2><h3 id="_1-lovable-web-based" tabindex="-1">1. Lovable (Web-based) <a class="header-anchor" href="#_1-lovable-web-based" aria-label="Permalink to “1. Lovable (Web-based)”">​</a></h3><ul><li><strong>Plattform-Typ:</strong> Web</li><li><strong>Haupteigenschaften und Workflow:</strong> Lovable macht Integration und Zusammenarbeit gut, automatisiert Initialisierungen wie die Verbindung mit Supabase-Datenbank und macht den Projektaufbau sehr reibungslos. Sie beschreiben einfach die Projektanforderungen, und der Agent verbindet alle Dienste und erstellt die Grundstruktur.</li><li><strong>Geeignete Nutzer:</strong> Für Einsteiger, die zum ersten Mal Vibe Coding ausprobieren, ist Lovable eine sehr freundliche Wahl. Es vereinfacht die Komplexität der Mehrdienst-Verkettung und lässt Sie sich auf Prompts und Iterationen konzentrieren statt auf Umgebungskonfiguration. Dank hoher Automatisierung erhalten Sie schnell einen lauffähigen Prototyp.</li><li><strong>Prompt-Prozess:</strong><img src="'+l+'" alt=""></li><li><strong>Snake-Spiel-Ergebnis:</strong></li></ul><p><img src="'+o+'" alt=""><img src="'+d+'" alt=""></p><ul><li><strong>Preis:</strong> Relativ teuer, aber mit einer Uni-E-Mail können Sie durch Studenten-Verifizierung den halben Preis erhalten. <img src="'+g+'" alt=""></li></ul><h3 id="_2-cursor-ide" tabindex="-1">2. Cursor (IDE) <a class="header-anchor" href="#_2-cursor-ide" aria-label="Permalink to “2. Cursor (IDE)”">​</a></h3><ul><li><strong>Plattform-Typ:</strong> Desktop-Anwendung (PC)</li><li><strong>Haupteigenschaften und Workflow:</strong> Cursor ist eine proprietäre IDE mit integrierten AI-Fähigkeiten, unterstützt Windows, macOS und Linux. Es baut Codegenerierung, intelligentes Umschreiben und Codebasis-Abfrage direkt in die Entwicklungsumgebung ein. Im Vergleich zu Web-Tools ist es näher an der traditionellen lokalen Entwicklungserfahrung. Da es eine lokale Umgebung ist, variieren die Konfigurationen verschiedener Computer, was gelegentlich zu umgebungsbezogenen Problemen führen kann. Der Vorteil: Das Projekt ist lokal, keine zusätzte Download- oder Laufzeitumgebung nötig, Cursor erledigt viele mühsame Schritte für Sie.</li><li><strong>Geeignete Nutzer:</strong> Für Nutzer mit gewissen Programmierkenntnissen ist Cursor eine sehr leistungsstarke und vertraute Umgebung. Für absolute Einsteiger ohne Vorkenntnisse ist die Lernkurve jedoch steiler, da man selbst Projektstruktur, Abhängigkeitsmanagement und Dateiorganisation verstehen muss. Besser geeignet für Entwickler, die AI-Unterstützung in ihren traditionellen Codierungs-Workflow integrieren wollen.</li><li><strong>Prompt-Prozess:</strong><img src="'+u+'" alt=""></li><li><strong>Snake-Spiel-Ergebnis:</strong></li></ul><p><img src="'+h+'" alt=""><img src="'+m+'" alt=""></p><ul><li><strong>Preis:</strong><img src="'+c+'" alt=""></li></ul><h3 id="_3-z-ai-web-based" tabindex="-1">3. Z.ai (Web-based) <a class="header-anchor" href="#_3-z-ai-web-based" aria-label="Permalink to “3. Z.ai (Web-based)”">​</a></h3><ul><li><strong>Plattform-Typ:</strong> Web</li><li><strong>Haupteigenschaften und Workflow:</strong> Z.ai ist relativ direkt zu bedienen, aber eine offensichtliche Herausforderung ist: Sie müssen den generierten Code <strong>manuell kopieren und einfügen</strong>. Die Plattform selbst hat kein Echtzeit-Vorschaufenster, sodass man die Code-Ausführung nicht sofort sehen kann.</li><li><strong>Geeignete Nutzer:</strong> Diese Plattform erfordert einen &quot;hands-on&quot; Ansatz. Fehlende Automatisierung bedeutet, dass Sie direkt mit dem Code arbeiten müssen, was für Leute, die AI-Outputs tief verstehen wollen, eine Art Training ist. Häufiges Kopieren und Einfügen bringt jedoch Effizienzprobleme und Fehler Risiken mit sich. Besser geeignet für Leute, die &quot;rohe AI-Code-Outputs&quot; sehen wollen, nicht für diejenigen, die ein One-Click-Erlebnis suchen.</li><li><strong>Prompt-Prozess:</strong><img src="'+b+'" alt=""></li><li><strong>Snake-Spiel-Ergebnis:</strong></li></ul><p><img src="'+p+'" alt=""><img src="'+f+'" alt=""></p><ul><li><strong>Preis:</strong><img src="'+k+'" alt=""></li></ul><h3 id="_4-replit-web-based" tabindex="-1">4. Replit (Web-based) <a class="header-anchor" href="#_4-replit-web-based" aria-label="Permalink to “4. Replit (Web-based)”">​</a></h3><ul><li><p><strong>Plattform-Typ:</strong> Web</p></li><li><p><strong>Haupteigenschaften und Workflow:</strong> Replit ist eine All-in-One Online-Entwicklungs- und Bereitstellungsumgebung. Im Browser können Sie Code schreiben, Programme ausführen und eine Online-Zugriffs-URL generieren. Vor dem Codieren zeigt es einen klaren Aktionsplan; außerdem gibt es einen visuellen Editor, in dem Sie direkt im Vorschaufenster die UI ändern können, und der Quellcode wird automatisch synchronisiert. So können Sie jederzeit überprüfen, ob die AI-Ausgabe Ihren Erwartungen entspricht, und die Anzahl der Hin- und Her-Korrekturen erheblich reduzieren.</p><p><img src="'+w+'" alt=""></p></li><li><p><strong>Geeignete Nutzer:</strong> Replit ist sehr einsteigerfreundlich. Es vereinfacht den vollständigen Kreislauf von der Codierung bis zur Bereitstellung, ohne zusätzte Server- oder Hosting-Konfiguration. Die Kollaborationsfunktion ist ebenfalls stark, ideal für Gruppenprojekte unter Kommilitonen oder Remote-Hilfe.</p></li><li><p><strong>Prompt-Prozess:</strong> Während des Aufbaus verstand die AI die Anforderungen nicht sofort; es dauerte etwa 3 Iterationsrunden, bis das Ergebnis zufriedenstellend war. <img src="'+P+'" alt=""></p></li><li><p><strong>Snake-Spiel-Ergebnis:</strong></p></li></ul><p><img src="'+z+'" alt=""><img src="'+v+'" alt=""></p><ul><li><strong>Preis:</strong><img src="'+S+'" alt=""></li></ul><h3 id="_5-minimax-web-based" tabindex="-1">5. Minimax (Web-based) <a class="header-anchor" href="#_5-minimax-web-based" aria-label="Permalink to “5. Minimax (Web-based)”">​</a></h3><ul><li><strong>Plattform-Typ:</strong> Web</li><li><strong>Haupteigenschaften und Workflow:</strong> Minimax benötigt bei der Aufgabenausführung oft länger. Der Prozess umfasst häufig: AI entdeckt und repariert automatisch Fehler, daher kann der gesamte Prozess langsam oder etwas mühsam sein. In diesem Projekt erstellt der Agent zunächst einen detaillierten Plan und baut dann Schritt für Schritt Backend, Datenbank und Frontend-Logik auf.</li><li><strong>Geeignete Nutzer:</strong> Da es automatisch Tests ausführt und Fehler repariert, sind Zeit- und Token-Verbrauch hoch, aber man kann klar sehen, wie AI Probleme lokalisiert und löst, was aus Lernperspektive sehr wertvoll ist.</li><li><strong>Prompt-Prozess:</strong></li></ul><p><img src="'+A+'" alt=""><img src="'+_+'" alt=""><img src="'+I+'" alt=""><img src="'+W+'" alt=""></p><ul><li><strong>Snake-Spiel-Ergebnis:</strong></li></ul><p><img src="'+E+'" alt=""><img src="'+D+'" alt=""></p><ul><li><strong>Preis:</strong> Die kostenlose Version kann bei komplexen Projekten wahrscheinlich nicht vollständig durchlaufen, daher wird ein kostenpflichtiges Upgrade empfohlen, um sicherzustellen, dass das Projekt vollständig erstellt werden kann. <img src="'+C+'" alt=""></li></ul><h3 id="_6-trae-ide" tabindex="-1">6. Trae (IDE) <a class="header-anchor" href="#_6-trae-ide" aria-label="Permalink to “6. Trae (IDE)”">​</a></h3><ul><li><strong>Plattform-Typ:</strong> Desktop-Anwendung (PC)</li><li><strong>Haupteigenschaften und Workflow:</strong> Als Desktop-Anwendung hat Trae gegenüber Web-Tools normalerweise Vorteile bei Leistung und Reaktionsgeschwindigkeit. Es erfordert jedoch Download und Installation, was für einige Nutzer eine etwas höhere Einstiegshürde darstellt. Da es eine lokale Umgebung ist, bringen unterschiedliche Computerkonfigurationen und Abhängigkeitsumgebungen eine gewisse Unsicherheit mit sich. Der Vorteil: Trae hilft Ihnen, Projekterstellung und Laufzeitkonfiguration lokal abzuschließen; Sie können direkt auf Ihrem Rechner entwickeln und debuggen.</li><li><strong>Geeignete Nutzer:</strong> Besser geeignet für Nutzer, die langfristig Vibe Coding-Projekte betreiben und ein spezielles Desktop-Tool verwenden möchten. Für Gelegenheitsnutzer ist es möglicherweise nicht die leichteste Wahl.</li><li><strong>Prompt-Prozess:</strong><img src="'+V+'" alt=""></li><li><strong>Snake-Spiel-Ergebnis:</strong></li></ul><p><img src="'+x+'" alt=""><img src="'+q+'" alt=""></p><ul><li><strong>Preis:</strong> Preis relativ günstig, selbst die kostenlose Version reicht für qualitativ gute kleine Projekte. <img src="'+T+'" alt=""></li></ul><h3 id="_7-v0-web-based" tabindex="-1">7. V0 (Web-based) <a class="header-anchor" href="#_7-v0-web-based" aria-label="Permalink to “7. V0 (Web-based)”">​</a></h3><ul><li><p><strong>Plattform-Typ:</strong> Web</p></li><li><p><strong>Haupteigenschaften und Workflow:</strong> V0 ist ein Tool von Vercel, das sich auf die Generierung von React-UI-Komponenten konzentriert. Es zeichnet sich durch die Erzeugung hochwertiger, produktionsreifer Oberflächen aus. In der Praxis kann man jedoch auf Probleme stoßen wie &quot;Code-Ansicht schwer zu finden&quot; oder &quot;keine klare Angabe, wo der API Key konfiguriert werden sollte&quot;.</p></li><li><p><strong>Geeignete Nutzer:</strong> V0 ist sehr geeignet für Studierende oder Designer, die sich auf Frontend und UI/UX-Design konzentrieren. Es ist jedoch keine vollständige Full-Stack-Lösung; Sie benötigen weiterhin andere Plattformen für Backend-Logik und API-Integration. Wenn Ihr Ziel &quot;ein komplettes Projekt in einem Durchgang&quot; ist, ist es möglicherweise nicht die beste Erstwahl.</p></li><li><p><strong>Prompt-Prozess:</strong><img src="'+K+'" alt=""></p><p><img src="'+B+'" alt=""></p></li><li><p><strong>Snake-Spiel-Ergebnis:</strong><img src="'+G+'" alt=""><img src="'+N+'" alt=""></p></li><li><p><strong>Preis:</strong> Kostenlose Nutzer können etwa 4-5 einfache Projekte erstellen. <img src="'+U+'" alt=""></p></li></ul><h2 id="_3-plattform-gesamtvergleich" tabindex="-1">3. Plattform-Gesamtvergleich <a class="header-anchor" href="#_3-plattform-gesamtvergleich" aria-label="Permalink to “3. Plattform-Gesamtvergleich”">​</a></h2><table tabindex="0"><thead><tr><th><strong>Plattform</strong></th><th><strong>Bewertung</strong></th><th><strong>Plattform</strong></th><th><strong>Anmerkungen</strong></th></tr></thead><tbody><tr><td><strong><a href="https://lovable.dev/" target="_blank" rel="noreferrer">Lovable</a></strong></td><td>Sehr freundlich für AI-Programmier-Einsteiger, einfacher Einstieg, reibungslose Erfahrung, ideal als Erstwahl.</td><td>Web-based</td><td>Automatisiert Supabase- und andere Dienstverbindungen, reduziert Konfigurationsaufwand.</td></tr><tr><td><strong><a href="https://cursor.com/cn/agents" target="_blank" rel="noreferrer">Cursor</a></strong></td><td>Geeignet für Nutzer mit Entwicklungserfahrung, steigert Produktivität und Code-Qualität erheblich.</td><td>PC</td><td>Erfordert gewisse Programmierkenntnisse, lokales Umfeld erfordert eigenes Verständnis von Projektstruktur und Abhängigkeiten.</td></tr><tr><td><strong><a href="https://chat.z.ai/" target="_blank" rel="noreferrer">Z.ai</a></strong></td><td>Besser geeignet für Nutzer mit Programmierkenntnissen, die AI-Code-Output-Details direkt untersuchen wollen.</td><td>Web-based</td><td>Kein Vorschaufenster, Ergebnisprüfung mühsam; Code manuell kopieren, Ordner und Dateien manuell erstellen und Service manuell starten.</td></tr><tr><td><strong><a href="https://replit.com/~" target="_blank" rel="noreferrer">Replit</a></strong></td><td>Empfohlen für Nutzer, die Ideen schnell zu zugänglichen Online-Services machen wollen.</td><td>Web-based</td><td>All-in-One Online-Entwicklung und -Bereitstellung, unterstützt Kollaboration und bietet visuellen Editor.</td></tr><tr><td><strong><a href="https://agent.minimaxi.com/" target="_blank" rel="noreferrer">Minimax</a></strong></td><td>Geeignet für Leute, die den gesamten AI-Fehlererkennungs- und -Reparaturprozess sehen und daraus lernen wollen, aber insgesamt langsamer und token-intensiv.</td><td>Web-based</td><td>Längerer Gesamtprozess, AI führt mehrfach automatisch Tests aus und repariert Fehler.</td></tr><tr><td><strong><a href="https://www.trae.ai/" target="_blank" rel="noreferrer">Trae</a></strong></td><td>Für Nutzer mit Programmiererfahrung, die Desktop-IDE + AI Agent kombinieren wollen, ein leistungsstarkes Effizienz-Tool.</td><td>PC</td><td>Lokale Installation und Umgebungskonfiguration erforderlich, aber bessere Leistung, geeignet für langfristige Vibe Coding-Projekte.</td></tr><tr><td><strong><a href="https://v0.app/" target="_blank" rel="noreferrer">V0</a></strong></td><td>Optimiert für Nicht-Entwickler, die schnell React-UI erstellen wollen, geeignet für Frontend-/Design-orientierte Studierende.</td><td>Web-based</td><td>Fokussiert auf React-UI-Generierung, muss mit anderen Plattformen für Backend und vollständigen App-Aufbau kombiniert werden.</td></tr></tbody></table><hr><h2 id="title-vergleich-von-7-ki-programmiertools-description-praxisnaher-vergleich-von-web-vibe-coding-plattformen-mit-einer-einheitlichen-aufgabe-bedienbarkeit-code-kontrolle-und-deployment" tabindex="-1">title: &#39;Vergleich von 7 KI-Programmiertools&#39; description: &#39;Praxisnaher Vergleich von Web-Vibe-Coding-Plattformen mit einer einheitlichen Aufgabe: Bedienbarkeit, Code-Kontrolle und Deployment.&#39; <a class="header-anchor" href="#title-vergleich-von-7-ki-programmiertools-description-praxisnaher-vergleich-von-web-vibe-coding-plattformen-mit-einer-einheitlichen-aufgabe-bedienbarkeit-code-kontrolle-und-deployment" aria-label="Permalink to “title: &#39;Vergleich von 7 KI-Programmiertools&#39;description: &#39;Praxisnaher Vergleich von Web-Vibe-Coding-Plattformen mit einer einheitlichen Aufgabe: Bedienbarkeit, Code-Kontrolle und Deployment.&#39;”">​</a></h2>',97)])])}const X=n(F,[["render",L]]);export{H as __pageData,X as default};
